474	  if(!name || !phone){ alert('請填寫姓名與手機號碼'); return; }
475	
476	  // fire-and-forget：寫進資料庫＋發 Telegram 給教練與佩佩老師。
477	  // 任何失敗都不能擋住付款——報名的人不該因為我們後台的問題而卡住。
478	  PLANS[currentPlan].slugs.forEach(slug => {
479	    fetch(BYMYWAY_API, {
480	      method: 'POST',
481	      headers: { 'Content-Type': 'application/json' },
482	      body: JSON.stringify({ slug, name, phone, company, email, source: 'ai-forum-taichung（台中場' + (currentPlan === 'combo' ? '・兩天套票' : '・單日') + '）' })
483	    }).catch(()=>{});
484	  });
485	
486	  closeRegister();
487	  window.open(PAYMENT_URL, '_blank', 'noopener');
488	}
