491	function updateCountdown(){
492	  const target = new Date('2026-09-23T09:00:00+08:00').getTime();
493	  const now = Date.now();
494	  const diff = target - now;
495	  if(diff <= 0){ document.getElementById('cd-d').textContent='0'; document.getElementById('cd-h').textContent='0'; document.getElementById('cd-m').textContent='0'; return; }
496	  const d = Math.floor(diff/86400000);
497	  const h = Math.floor((diff%86400000)/3600000);
498	  const m = Math.floor((diff%3600000)/60000);
499	  document.getElementById('cd-d').textContent = d;
500	  document.getElementById('cd-h').textContent = h;
501	  document.getElementById('cd-m').textContent = m;
502	}
503	updateCountdown();
504	setInterval(updateCountdown, 60000);
